// (C_in=3, kD=kH=3, kW=1, stride=1, padding=0, dilation=1, groups=1).
// Each CTA computes a 128-pixel x 64-output-channel tile for up to two
// adjacent output-depth slices. The shared input patch stages kD + 1
// depth planes, so the second output slice reuses the overlapped depth
// halo while the whole 64 x 27 weight matrix is loaded only once. A
// 32 x 8 thread block gives every thread a 4-pixel x 8-channel
// micro-tile. The 27-tap reduction is fully unrolled, and outputs are
// committed as aligned float4 stores when the plane tail permits.
__global__ void __launch_bounds__(256) conv3d_tiled_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    long long total,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    int groups,
    int has_bias,
    int sh_in, int sw_in)
{
    extern __shared__ float smem[];
    const int HW = H_out * W_out;
    const int taps = C_in * kD * kH * kW;
    const int tile_depth = kD + 1, in_elems = C_in * (kD + 1) * sh_in * sw_in;
    float* tile = smem;                    // [C_in][kD][sh_in][sw_in]
    float* wsm = smem + in_elems;          // [C_out][taps], groups == 1
    const int nthreads = blockDim.x * blockDim.y;
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int p0 = blockIdx.x * 128;
    const int dz = (D_out + 1) / 2, do0 = (int)(blockIdx.z % dz) * 2;
    const int n = (int)(blockIdx.z / dz);
    const int ho_min = p0 / W_out;
    const int hi0 = ho_min * sH - pH;
    const int wi0 = -pW;
    const int di0 = do0 * sD - pD;
    for (int i = tid; i < in_elems; i += nthreads) {
        int wi_l = i % sw_in;
        int t = i / sw_in;
        int hi_l = t % sh_in;
        t /= sh_in;
        int kd = t % tile_depth;
        int c = t / tile_depth;
        int wi = wi0 + wi_l;
        int hi = hi0 + hi_l;
