    }
    __syncthreads();
    const int tx = threadIdx.x;  // 32 pixel groups of 4 consecutive pixels
    const int ty = threadIdx.y;  // 8 channel groups of 8 channels
    const int p_base = p0 + tx * 4;
    const int co0 = ty * 8;
    int ho[4], hb[4], wb[4];
    bool pv[4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int p = p_base + i;
        pv[i] = p < HW;
        int pp = pv[i] ? p : (ho_min * W_out);
        ho[i] = pp / W_out;
        int wo = pp - ho[i] * W_out;
        hb[i] = (ho[i] - ho_min) * sH;
        wb[i] = wo * sW;
    }
    const long long ystride = (long long)D_out * HW;
    for (int od = 0; od < 2; ++od) {
        const int do_out = do0 + od;
        if (do_out >= D_out) break;
        float acc[8][4];
        #pragma unroll
        for (int j = 0; j < 8; ++j) {
            float bv = has_bias ? b[co0 + j] : 0.0f;
            #pragma unroll
            for (int i = 0; i < 4; ++i) acc[j][i] = bv;
        }
        int t = 0;
        #pragma unroll
        for (int c = 0; c < 3; ++c) {
            #pragma unroll
            for (int kd = 0; kd < 3; ++kd) {
                const float* tcd = tile + ((long long)c * tile_depth + kd + od) * sh_in * sw_in;
                #pragma unroll
                for (int kh = 0; kh < 3; ++kh) {
                    float av[4];
                    #pragma unroll
                    for (int i = 0; i < 4; ++i) {
                        av[i] = pv[i] ? tcd[(long long)(hb[i] + kh * dH) * sw_in + wb[i]] : 0.0f;
