                    float wv[8];
                    #pragma unroll
                    for (int j = 0; j < 8; ++j) {
                        wv[j] = wsm[(co0 + j) * taps + t];
                    }
                    #pragma unroll
                    for (int j = 0; j < 8; ++j) {
                        #pragma unroll
                        for (int i = 0; i < 4; ++i) {
                            acc[j][i] += av[i] * wv[j];
