}
// Register-blocked variant of the tiled kernel (the ONE optimization
// applied here: register blocking over the output-pixel dimension).
// The profiler shows the tiled kernel is compute-pipe bound at 92% with
// full occupancy: every output channel iteration re-loads the SAME 27
// shared-memory input taps plus 27 weight values for a single FMA each,
// so the load pipeline -- not the FMA pipe -- is the bottleneck.
// Here each thread owns TWO output pixels (strided by blockDim.x so
// stores stay coalesced) and preloads the C_in*kD*kH*kW input taps for
// both pixels into registers exactly once. The output-channel loop then
// issues a single broadcast weight load per tap that feeds BOTH pixels'
// FMAs. This removes the C_out-times redundant shared-memory reloads of
// identical input values and halves the weight-load instruction stream
// per output element, roughly doubling the FMA:load ratio.
#define CONV3D_MAX_TAPS 32
__global__ void __launch_bounds__(128) conv3d_tiled_reg_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    long long total,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    int groups,
    int has_bias,
    int sh_in, int sw_in)
{
    extern __shared__ float tile[];  // [C_in][kD][sh_in][sw_in]
    const int HW = H_out * W_out;
    const int span = blockDim.x * 2;   // output pixels covered per CTA
    int p0  = blockIdx.x * span;
    int do_ = blockIdx.z % D_out;
    int n   = blockIdx.z / D_out;
    int ho_min = p0 / W_out;
    int hi0 = ho_min * sH - pH;
    int wi0 = -pW;
    int di0 = do_ * sD - pD;
    // Cooperative load of the input patch (identical to the tiled
    // kernel), zero-filled outside the input so taps are branch-free.
    int tile_elems = C_in * kD * sh_in * sw_in;
    for (int i = threadIdx.x; i < tile_elems; i += blockDim.x) {
        int wi_l = i % sw_in;
        int t = i / sw_in;
        int hi_l = t % sh_in;
        t /= sh_in;
        int kd = t % kD;
        int c  = t / kD;
        int wi = wi0 + wi_l;
        int hi = hi0 + hi_l;
        int di = di0 + kd * dD;
        float v = 0.0f;
        if (wi >= 0 && wi < W_in && hi >= 0 && hi < H_in && di >= 0 && di < D_in) {
            v = x[(((long long)n * C_in + c) * D_in + di) * (long long)H_in * W_in
                  + (long long)hi * W_in + wi];
        }
        tile[i] = v;
    }
    __syncthreads();
    const int taps = C_in * kD * kH * kW;  // groups == 1, <= CONV3D_MAX_TAPS
    int pA = p0 + threadIdx.x;
    if (pA >= HW) return;                 // pB > pA is out of range too
    int pB = pA + blockDim.x;
    bool validB = pB < HW;
    int hoA = pA / W_out;
    int woA = pA - hoA * W_out;
    int hbA = (hoA - ho_min) * sH;
    int wbA = woA * sW;
    int hoB = validB ? pB / W_out : 0;
    int woB = validB ? pB - hoB * W_out : 0;
    int hbB = (hoB - ho_min) * sH;
    int wbB = woB * sW;
    // Stage both pixels' input taps in registers. The unrolled loop gives
    // compile-time array indices (no local-memory spill); tap order
    // matches the weight layout (c, kd, kh, kw).
    float inA[CONV3D_MAX_TAPS];
    float inB[CONV3D_MAX_TAPS];
    #pragma unroll
    for (int t = 0; t < CONV3D_MAX_TAPS; ++t) {
        if (t < taps) {
            int r1 = t / kW;
            int kw = t - r1 * kW;
            int r2 = r1 / kH;
            int kh = r1 - r2 * kH;
            int r3 = r2 / kD;
            int kd = r2 - r3 * kD;
            int c  = r3;
            const float* base = tile + ((long long)c * kD + kd) * sh_in * sw_in;
            inA[t] = base[(hbA + kh * dH) * sw_in + wbA + kw * dW];
            inB[t] = validB ? base[(hbB + kh * dH) * sw_in + wbB + kw * dW] : 0.0f;
        } else {
            inA[t] = 0.0f;
            inB[t] = 0.0f;
        }
    }
    const long long ystride = (long long)D_out * HW;
    long long ybase = (((long long)n * C_out) * D_out + do_) * (long long)HW;
    for (int co = 0; co < C_out; ++co) {
        const float* wco = w + (long long)co * taps;
        float accA = has_bias ? b[co] : 0.0f;
        float accB = accA;
        #pragma unroll
        for (int t = 0; t < CONV3D_MAX_TAPS; ++t) {
            if (t < taps) {
                float wv = wco[t];  // warp-uniform broadcast load, reused 2x
                accA += inA[t] * wv;
                accB += inB[t] * wv;
            }
        }
        __stcs(&y[ybase + (long long)co * ystride + pA], accA);
        if (validB) __stcs(&y[ybase + (long long)co * ystride + pB], accB);
    }
}
// Implicit-GEMM tiled kernel for the exact benchmark shape
// (C_in=3, kD=kH=3, kW=1, stride=1, padding=0, dilation=1, groups=1).
// Each CTA computes a 128-pixel x 64-output-channel tile for one
// (n, do) slice. The input patch and the whole 64 x 27 weight matrix
// are staged once in shared memory; a 32 x 8 thread block then gives
// every thread a 4-pixel x 8-channel micro-tile. The 27-tap reduction
// is fully unrolled, each tap does 4 shared input loads + 8 broadcast
// shared weight loads feeding 32 FMAs, and outputs are committed as
// aligned float4 stores when the plane tail permits.
__global__ void __launch_bounds__(256) conv3d_tiled_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    long long total,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int dD, int dH, int dW,
    int groups,
    int has_bias,
    int sh_in, int sw_in)
{
    extern __shared__ float smem[];
    const int HW = H_out * W_out;
    const int taps = C_in * kD * kH * kW;
    const int in_elems = C_in * kD * sh_in * sw_in;
    float* tile = smem;                    // [C_in][kD][sh_in][sw_in]
    float* wsm = smem + in_elems;          // [C_out][taps], groups == 1
    const int nthreads = blockDim.x * blockDim.y;
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int p0 = blockIdx.x * 128;
    const int do_ = blockIdx.z % D_out;
    const int n = blockIdx.z / D_out;
    const int ho_min = p0 / W_out;
    const int hi0 = ho_min * sH - pH;
    const int wi0 = -pW;
    const int di0 = do_ * sD - pD;
    for (int i = tid; i < in_elems; i += nthreads) {
        int wi_l = i % sw_in;
        int t = i / sw_in;
        int hi_l = t % sh_in;
        t /= sh_in;
        int kd = t % kD;
        int c = t / kD;
        int wi = wi0 + wi_l;
        int hi = hi0 + hi_l;
        int di = di0 + kd * dD;
        float v = 0.0f;
        if (wi >= 0 && wi < W_in && hi >= 0 && hi < H_in && di >= 0 && di < D_in) {
            v = x[(((long long)n * C_in + c) * D_in + di) * (long long)H_in * W_in
                  + (long long)hi * W_in + wi];
        }
        tile[i] = v;
    }
    const int w_elems = C_out * taps;
    for (int i = tid; i < w_elems; i += nthreads) {
        wsm[i] = w[i];
    }
    __syncthreads();
    const int tx = threadIdx.x;  // 32 pixel groups of 4 consecutive pixels
    const int ty = threadIdx.y;  // 8 channel groups of 8 channels
    const int p_base = p0 + tx * 4;
    const int co0 = ty * 8;
    int ho[4], hb[4], wb[4];
    bool pv[4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int p = p_base + i;
        pv[i] = p < HW;
        int pp = pv[i] ? p : (ho_min * W_out);
        ho[i] = pp / W_out;
        int wo = pp - ho[i] * W_out;
        hb[i] = (ho[i] - ho_min) * sH;
        wb[i] = wo * sW;
    }
    float acc[8][4];
    #pragma unroll
    for (int j = 0; j < 8; ++j) {
        float bv = has_bias ? b[co0 + j] : 0.0f;
        #pragma unroll
        for (int i = 0; i < 4; ++i) acc[j][i] = bv;
    }
    int t = 0;
    #pragma unroll
    for (int c = 0; c < 3; ++c) {
        #pragma unroll
        for (int kd = 0; kd < 3; ++kd) {
            const float* tcd = tile + ((long long)c * kD + kd) * sh_in * sw_in;
            #pragma unroll
            for (int kh = 0; kh < 3; ++kh) {
                float av[4];
                #pragma unroll
                for (int i = 0; i < 4; ++i) {
                    av[i] = pv[i] ? tcd[(long long)(hb[i] + kh * dH) * sw_in + wb[i]] : 0.0f;
                }
                float wv[8];
                #pragma unroll
                for (int j = 0; j < 8; ++j) {
                    wv[j] = wsm[(co0 + j) * taps + t];
                }
                #pragma unroll
                for (int j = 0; j < 8; ++j) {
                    #pragma unroll
                    for (int i = 0; i < 4; ++i) {
                        acc[j][i] += av[i] * wv[j];
                    }
                }
                ++t;
            }
        }
    }
    const long long ystride = (long long)D_out * HW;
    const long long ybase = (((long long)n * C_out) * D_out + do_) * (long long)HW;
    #pragma unroll
    for (int j = 0; j < 8; ++j) {
        float* out = y + ybase + (long long)(co0 + j) * ystride;
        if (p_base + 3 < HW) {
            *reinterpret_cast<float4*>(out + p_base) =
                make_float4(acc[j][0], acc[j][1], acc[j][2], acc[j][3]);
        } else {
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                if (pv[i]) out[p_base + i] = acc[j][i];
            }
        }
    }
}
